def fig_block(n, figs):
    out = []
    for nn, slug, arch, brief in figs:
        out.append(f"- **Figure {int(n)}.{int(nn)}** `@fig:{slug}`, file `assets/woodcuts/{n}-{nn}-{slug}.png`, archetype *{arch}*: {brief}.")
    return "\n".join(out)

for n, slug, title, words, aheads, figs, plate, sidebar in CH:
    b = TPL
    b = b.replace("{N}", str(int(n))).replace("{NN}", n).replace("{Title}", title).replace("{slug}", slug)
    b = b.replace("{WORDS}", f"{words:,}")
    b = b.replace("{AHEADS}", "\n  ".join(f"{i+1}. {a}" for i, a in enumerate(aheads)))
    b = b.replace("{FIGURES}", fig_block(n, figs))
    b = b.replace("{PLATES}", plate or "This chapter has no plate.")
    b = b.replace("## Sidebars and admonitions\n\nOne sidebar of 150 to 400 words,", f"## Sidebars and admonitions\n\nSuggested sidebar material: {sidebar}.\n\nOne sidebar of 150 to 250 words,")
    (ROOT / f"docs/briefs/brief-{n}.md").write_text(b)
    print("wrote", n, title)
